reveal.code:
variable "environment" {
  type        = string
  description = "Deployment environment"
  default     = "dev"
}

variable "ports" {
  type    = list(number)
  default = [80, 443]
}

output "vpc_id" {
  description = "ID of the application VPC"
  value       = aws_vpc.app.id
}

locals {
  normalized_env = lower(var.environment)
  common_tags = merge(
    var.base_tags,
    { Environment = local.normalized_env }
  )
}

output "safe_name" {
  value = try(var.optional_name, "default")
}

resource "terraform_data" "service" {
  for_each = {
    api = "v1"
    web = "v2"
  }

  input = {
    name    = each.key
    version = each.value
  }
}

resource "aws_instance" "app" {
  ami           = var.ami_id
  instance_type = "t3.micro"

  lifecycle {
    create_before_destroy = true
    prevent_destroy       = true
  }
}

variable "cidr" {
  type = string

  validation {
    condition     = can(cidrnetmask(var.cidr))
    error_message = "cidr must use valid CIDR notation"
  }
}

variable "api_token" {
  type      = string
  sensitive = true
  ephemeral = true
}

ephemeral "random_password" "db" {
  length = 24
}
